"""Quote helpers shared by services: status updates and loading a chosen quote."""

from __future__ import annotations

import json
import re
from typing import Any, Optional

from psycopg import Connection

from ..db import fetch_one, now_iso, transaction

#: Offer ids as generated by the offer service (``OFF-`` + 10 hex/upper chars).
OFFER_ID_RE = re.compile(r"\bOFF-[A-Z0-9]{10}\b")


def mark_ordered(offer_id: str, conn: Optional[Connection] = None) -> bool:
    """Mark a quote as ordered. Returns True when a row was updated."""
    sql = "UPDATE quotes SET status = 'ordered', updated_at = %s WHERE offer_id = %s"
    params = (now_iso(), offer_id)
    if conn is not None:
        return conn.execute(sql, params).rowcount > 0
    with transaction() as own:
        return own.execute(sql, params).rowcount > 0


def load_offer_context(offer_id: str, customer_id: str) -> Optional[dict[str, Any]]:
    """``offer_context`` for an active quote of ``customer_id``, or ``None``.

    Used by the gateway when the customer picks one of several quotes
    (spec: generative-ui, quote selection). Quotes of other customers and
    expired/ordered quotes are never returned.
    """
    row = fetch_one(
        "SELECT offer_id, customer_id, company_name, items_json, term_months, total_price, "
        "monthly_total, total_discount FROM quotes "
        "WHERE offer_id = %s AND customer_id = %s AND status = 'active'",
        (offer_id, customer_id),
    )
    if not row:
        return None
    try:
        items = json.loads(row.get("items_json") or "[]")
    except (TypeError, ValueError):
        items = []
    context = {
        "offer_id": row["offer_id"],
        "customer_id": row["customer_id"],
        "company_name": row.get("company_name"),
        "items": items,
        "term_months": row.get("term_months"),
        "total_price": row.get("total_price"),
        "monthly_total": row.get("monthly_total"),
        "total_discount": row.get("total_discount"),
        "selected": True,
    }
    return json.loads(json.dumps(context, default=str))
